edits.old:
results = []
for item in iter:
    self.set_value(comp.target.id, item)
    results.append(self.visit(node.elt))
return tl_tuple(results)

edits.new:
results = []
for item in iter:
    self.set_value(comp.target.id, item)
    for predicate in comp.ifs:
        cond = _unwrap_if_constexpr(self.visit(predicate))
        if type(cond) not in _condition_types:
            raise self._unsupported(
                predicate, "comprehension conditions must be compile-time values of type {{{}}}, "
                "not objects of type {}".format(
                    ', '.join(_.__name__ for _ in _condition_types),
                    type(cond).__name__))
        if not cond:
            break
    else:
        results.append(self.visit(node.elt))
return tl_tuple(results)
